                    .map(instanceName -> instanceName.trim())
                    .flatMap(instanceName -> {
                        if (StringUtil.isEmpty(instanceName)) {
                            LOGGER.warn("Instance name is empty, skipping");
                            return Optional.empty();
                        }
                        return parseInstanceId(instanceName);
                    })
