package com.huawei.oss.wireless.experienceassuranceservice.nbi.impl.service;

import static com.huawei.oss.wireless.experienceassuranceservice.common.impl.bean.SceneTypeEnum.VENUE;
import static com.huawei.oss.wireless.experienceassuranceservice.common.impl.constant.OpenApiConstants.CIVIC_AREA;
import static com.huawei.oss.wireless.experienceassuranceservice.common.impl.constant.OpenApiConstants.INFEASIBILITY_REASON;
