        }
        ExpectationContext infeasibilityReason = new ExpectationContext();
        infeasibilityReason.setContextAttribute(INFEASIBILITY_REASON);
        infeasibilityReason.setContextCondition(IS_EQUAL_TO);
        infeasibilityReason.setContextValueRange(reason.toString());
