package com.huawei.oss.wireless.experienceassuranceservice.nbi.impl.service;

import static com.huawei.oss.wireless.experienceassuranceservice.common.impl.bean.SceneTypeEnum.VENUE;
import static com.huawei.oss.wireless.experienceassuranceservice.common.impl.constant.OpenApiConstants.CIVIC_AREA;
import static com.huawei.oss.wireless.experienceassuranceservice.common.impl.constant.OpenApiConstants.INFEASIBILITY_REASON;
import static com.huawei.oss.wireless.experienceassuranceservice.common.impl.constant.OpenApiConstants.IS_EQUAL_TO;
import static com.huawei.oss.wireless.experienceassuranceservice.common.impl.constant.OpenApiConstants.NUM_OF_UE_TARGET;
import static com.huawei.oss.wireless.experienceassuranceservice.common.impl.constant.OpenApiConstants.PACKAGE_CODE;

import com.huawei.bsp.log.OssLog;
import com.huawei.bsp.log.OssLogFactory;
import com.huawei.oss.wireless.experienceassuranceservice.common.impl.bean.SceneTypeEnum;
import com.huawei.oss.wireless.experienceassuranceservice.common.impl.mapper.DataDbMapper;
import com.huawei.oss.wireless.experienceassuranceservice.model.tocallocation.third.CapacityPredictParam;
import com.huawei.oss.wireless.experienceassuranceservice.model.tocallocation.third.CapacityPredictResult;
