import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.StringJoiner;
import java.util.stream.Collectors;

/**
 * 返回结果组装
 *
 * @since 2026-01-16
 */
@Component
public class ResponseAssembler {
    private static final OssLog LOGGER = OssLogFactory.getLogger(ResponseAssembler.class);

    @Autowired private DataDbMapper dataDbMapper;

    /**
     * 组装返回值
     *
     * @param param param
     * @param sceneToResults sceneToResults
     * @return 返回值
     */
    public CapacityPredictResult buildResponse(CapacityPredictParam param,
        Map<CivicAddress, List<RegionResult>> sceneToResults) {
        CapacityPredictResult response = new CapacityPredictResult();
        IntentExplorationReport report = new IntentExplorationReport();

        report.setExpectationExplorationStatus("success");

        // 遍历意图期望列表
        List<ExpectationExplorationResult> results = param.getIntentExpectations()
            .stream()
            .map(exp -> buildExpectationResult(exp, sceneToResults))
            .collect(Collectors.toList());

        report.setExpectationExplorationResults(results);
        response.setIntentExplorationReport(report);
        LOGGER.info("alloc result: {}", response);
        return response;
    }

    // 2. 组装结果层 (Expectation -> Target)
    private ExpectationExplorationResult buildExpectationResult(IntentExpectation exp,
        Map<CivicAddress, List<RegionResult>> sceneToResults) {
        ExpectationExplorationResult result = new ExpectationExplorationResult();
        result.setExpectationId(exp.getExpectationId());
        List<TargetExplorationResult> targets = new ArrayList<>();

        // 获取入参中的场景信息
        Context inputCtx = exp.getExpectationObject().getObjectContexts().getFirst();
        CivicAddress inputAddr = inputCtx.getContextValueRange();

        // 从 Map 获取数据库数据
        List<RegionResult> results = sceneToResults.getOrDefault(inputAddr, new ArrayList<>());
        LOGGER.info("results: {}", results);
        // 构建 Target 结果
        for (RegionResult regionResult : results) {
            TargetExplorationResult target = new TargetExplorationResult();
            target.setTargetName(NUM_OF_UE_TARGET);
            target.setTargetCondition(IS_EQUAL_TO);
            String allocConfigValueByName = dataDbMapper.getAllocConfigValueByName(
                inputAddr.getLoc() + "#" + (StringUtils.isNotEmpty(regionResult.getBlockName())
                    ? regionResult.getBlockName()
                    : ""));
            if (StringUtils.isNotBlank(allocConfigValueByName)) {
                target.setTargetValueRange(String.valueOf(0));
            } else {
                target.setTargetValueRange(String.valueOf(regionResult.getResult()));
            }

            // 核心：处理 TargetExplorationResult 逻辑分支
            target.setTargetContexts(buildTargetContexts(inputAddr, regionResult));
            targets.add(target);
        }

        result.setTargetExplorationResults(targets);
        return result;
    }

    // 3. 组装上下文层 (处理多态：CivicArea/InfeasibilityReason/PackageCode)
    private List<ExpectationContext> buildTargetContexts(CivicAddress inputAddr, RegionResult regionResult) {
        List<ExpectationContext> contexts = new ArrayList<>();

        contexts.add(getCivicAddress(inputAddr, regionResult));
        String configName = inputAddr.getLoc() + "#" + (StringUtils.isNotEmpty(regionResult.getBlockName())
            ? regionResult.getBlockName()
            : "");
        String allocConfigValueByName = dataDbMapper.getAllocConfigValueByName(configName);
        LOGGER.info("allocConfigValueByName: {}, name : {}", allocConfigValueByName, configName);
        ExpectationContext infeasibilityReason;
        if (StringUtils.isNotBlank(allocConfigValueByName)) {
            infeasibilityReason = getInfeasibilityReason(allocConfigValueByName);
        } else {
            infeasibilityReason = getInfeasibilityReason(regionResult);
        }
        if (infeasibilityReason != null) {
            contexts.add(infeasibilityReason);
        }

        ExpectationContext packageCode = new ExpectationContext();
        packageCode.setContextAttribute(PACKAGE_CODE);
        packageCode.setContextCondition(IS_EQUAL_TO);
        packageCode.setContextValueRange(regionResult.getPackageCode());
        contexts.add(packageCode);

        return contexts;
    }

    private ExpectationContext getCivicAddress(CivicAddress inputAddr, RegionResult regionResult) {
        ExpectationContext civicAddress = new ExpectationContext();
        civicAddress.setContextAttribute(CIVIC_AREA);
        civicAddress.setContextCondition(IS_EQUAL_TO);

        // 构造出参专用的 CivicAddress (包含 ADDCODE)
        CivicAddress outputAddr = new CivicAddress(inputAddr.getCountry(), inputAddr.getA1(), inputAddr.getA3(),
            inputAddr.getPlc(), inputAddr.getLoc());
        if (SceneTypeEnum.VENUE.getSceneType() == regionResult.getSceneType()) {
            outputAddr.setAddCode(regionResult.getBlockName());
        } else if (SceneTypeEnum.TRANSPORT_HUB.getSceneType() == regionResult.getSceneType()
            || SceneTypeEnum.SCENIC_SPOT.getSceneType() == regionResult.getSceneType()) {
            outputAddr.setAddCode("0");
        }

        civicAddress.setContextValueRange(outputAddr);
        return civicAddress;
    }

    private ExpectationContext getInfeasibilityReason(String allocConfigValueByName) {
        LOGGER.info("Customization no alloc reason");
        ExpectationContext infeasibilityReason = new ExpectationContext();
        infeasibilityReason.setContextAttribute(INFEASIBILITY_REASON);
        infeasibilityReason.setContextCondition(IS_EQUAL_TO);
        infeasibilityReason.setContextValueRange(allocConfigValueByName);
        return infeasibilityReason;
    }

    private ExpectationContext getInfeasibilityReason(RegionResult regionResult) {
        StringJoiner reason = new StringJoiner(",");
        if (regionResult.getRemark() > 0) {
            reason.add(RegionReasonEnum.toEnum(regionResult.getRemark()).getReason());
        }
        if (regionResult.getResourceShortfallCell() > 0) {
            reason.add(RegionReasonEnum.LACK_RESOURCE_NUM.getReason() + regionResult.getResourceShortfallCell());
        }
        if (regionResult.getAbnormalCell() > 0) {
            reason.add(RegionReasonEnum.ABN_CELLS_NUM.getReason() + regionResult.getAbnormalCell());
        }
        if (regionResult.getDeactiveCell() > 0) {
            reason.add(RegionReasonEnum.NO_ACTIVE_NUM.getReason() + regionResult.getDeactiveCell());
        }
        if (StringUtils.isBlank(reason.toString())) {
            return null;
        }
        ExpectationContext infeasibilityReason = new ExpectationContext();
        infeasibilityReason.setContextAttribute(INFEASIBILITY_REASON);
        infeasibilityReason.setContextCondition(IS_EQUAL_TO);
        infeasibilityReason.setContextValueRange(reason.toString());
        return infeasibilityReason;
    }
