            // 核心：处理 TargetExplorationResult 逻辑分支
            target.setTargetContexts(buildTargetContexts(inputAddr, regionResult));
            targets.add(target);
        }

        result.setTargetExplorationResults(targets);
        return result;
    }

    // 3. 组装上下文层 (处理多态：CivicArea/InfeasibilityReason/PackageCode)
    private List<ExpectationContext> buildTargetContexts(CivicAddress inputAddr, RegionResult regionResult) {
        List<ExpectationContext> contexts = new ArrayList<>();

        contexts.add(getCivicAddress(inputAddr, regionResult));
        String configName = inputAddr.getLoc() + "#" + (StringUtils.isNotEmpty(regionResult.getBlockName())
            ? regionResult.getBlockName()
            : "");
