package com.huawei.oss.wireless.experienceassuranceservice.nbi.impl.service;

import static com.huawei.oss.wireless.experienceassuranceservice.common.impl.constant.Constants.PROVISION_PACKAGE_NUM;

import com.huawei.bsp.log.OssLog;
import com.huawei.bsp.log.OssLogFactory;
import com.huawei.bsp.remoteservice.exception.ServiceException;
import com.huawei.oss.wireless.experienceassuranceservice.common.impl.mapper.DataDbMapper;
import com.huawei.oss.wireless.experienceassuranceservice.delegate.tocallocation.ThirdPointAllocationServiceDelegate;
import com.huawei.oss.wireless.experienceassuranceservice.livespacealloc.impl.service.InferenceService;
import com.huawei.oss.wireless.experienceassuranceservice.model.packagemgr.ProvisionPackage;
import com.huawei.oss.wireless.experienceassuranceservice.model.tocallocation.ErrorCode;
import com.huawei.oss.wireless.experienceassuranceservice.model.tocallocation.third.GeoCoordinate;
import com.huawei.oss.wireless.experienceassuranceservice.model.tocallocation.third.PointExpectationExplorationResult;
import com.huawei.oss.wireless.experienceassuranceservice.model.tocallocation.third.PointRadioServiceExpectation;
import com.huawei.oss.wireless.experienceassuranceservice.model.tocallocation.third.ThirdPointAllocationQueryParam;
import com.huawei.oss.wireless.experienceassuranceservice.model.tocallocation.third.ThirdPointAllocationQueryResult;
import com.huawei.oss.wireless.experienceassuranceservice.model.tocallocation.third.context.PointContext;
import com.huawei.oss.wireless.experienceassuranceservice.nbi.impl.constant.TocApiChecker;
import com.huawei.oss.wireless.experienceassuranceservice.packagemgr.mapper.PackageMgrMapper;

import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

/**
 * 点位接口实现
 *
 * @since 2026-02-08
 */
@Service
public class ThirdPointAllocationServiceDelegateImpl implements ThirdPointAllocationServiceDelegate {
    private static final OssLog LOGGER = OssLogFactory.getLogger(ThirdPointAllocationServiceDelegate.class);

    private static final String POINT_ALLOC_SWITCH = "tocAllocEva.POINT_ALLOC_SWITCH";

    @Autowired private InferenceService inferenceService;

    @Autowired private DataDbMapper dataDbMapper;

    @Autowired private PackageMgrMapper packageMgrMapper;

    /**
     * 用于openApi获取点位是否可放号
     *
     * @param pointCapacityQueryParam openApi点位请求参数
     * @return ThirdPointAllocationQueryResult 点位是否可放号结果
     * @throws ServiceException ServiceException
     */
    @Override
    @TocApiChecker(group = "point")
    public ThirdPointAllocationQueryResult queryPointAllocResult(ThirdPointAllocationQueryParam pointCapacityQueryParam)
        throws ServiceException {
        String pointAllocSwitch = dataDbMapper.getAllocConfigValueByName(POINT_ALLOC_SWITCH);
        if (!"1".equals(pointAllocSwitch)) {
            // 放号开关未打开时，不进行后续步骤，返回不可用
            LOGGER.info("point alloc switch is closed.");
            throw new ServiceException(ErrorCode.POINT_SWITCH.getErrorCode(), "");
        }
        String packageCode = pointCapacityQueryParam.getIntentExpectations()
            .getFirst()
            .getExpectationTargets()
            .getFirst()
            .getTargetValueRange();

        List<String> existingPackages = Optional.ofNullable(packageMgrMapper.queryPackages())
            .orElse(Collections.emptyList())
            .stream()
            .filter(p -> p.getPackageType() == PROVISION_PACKAGE_NUM)
            .map(ProvisionPackage::getPackageCode)
            .filter(Objects::nonNull)
            .distinct()
            .toList();
        if (!existingPackages.contains(packageCode)) {
            // 套餐不存在
            LOGGER.info("create scene failed, because of package not exist: {}", packageCode);
            throw new ServiceException(ErrorCode.OBJECT_MISS.getErrorCode(), "package");
        }
        ThirdPointAllocationQueryResult infeasibleByConfig = getInfeasibleByConfig(pointCapacityQueryParam);
        if (Objects.nonNull(infeasibleByConfig)) {
            return infeasibleByConfig;
        }
        return inferenceService.queryThirdPointAllocResult(pointCapacityQueryParam);
    }

    private ThirdPointAllocationQueryResult getInfeasibleByConfig(
        ThirdPointAllocationQueryParam pointCapacityQueryParam) {
        PointRadioServiceExpectation serviceExpectation = pointCapacityQueryParam.getIntentExpectations().getFirst();
        GeoCoordinate geoCoordinate = serviceExpectation.getExpectationObject()
            .getObjectContexts()
            .getFirst()
            .getContextValueRange();
        LOGGER.info("geoCoordinate.getLongitude() + \"#\" + geoCoordinate.getLatitude(): {}",
            geoCoordinate.getLongitude() + "#" + geoCoordinate.getLatitude());
        String allocConfigValueByName = dataDbMapper.getAllocConfigValueByName(
            geoCoordinate.getLongitude() + "#" + geoCoordinate.getLatitude());
        LOGGER.info("allocConfigValueByName: {}", allocConfigValueByName);
        if (StringUtils.isBlank(allocConfigValueByName)) {
            return null;
        }
        String[] configs = allocConfigValueByName.split("#");

        return buildPointAllocResult(configs[0], configs.length > 1 ? configs[1] : null);
    }

    private ThirdPointAllocationQueryResult buildPointAllocResult(String feasibilityCheckResult,
        String infeasibilityReasons) {
        ThirdPointAllocationQueryResult thirdPointAllocationQueryResult = new ThirdPointAllocationQueryResult();
        thirdPointAllocationQueryResult.setIntentFeasibilityCheckReport(
            new PointExpectationExplorationResult(feasibilityCheckResult, infeasibilityReasons));
        return thirdPointAllocationQueryResult;
    }
